<dialog class="workspace-dialog quicknav-dialog" id="quicknav-dialog" aria-labelledby="quicknav-title" aria-describedby="quicknav-help">
<div class="dialog-surface">
<div class="dialog-heading"><div><h2 id="quicknav-title">Buka halaman</h2><p class="muted">Pilih tujuan di ruang kerja Anda.</p></div><button class="dialog-close" type="button" data-close-dialog aria-label="Tutup pencarian halaman">×</button></div>
<label for="quicknav-search" class="visually-hidden">Cari halaman</label><input id="quicknav-search" type="search" autocomplete="off" placeholder="Cari nama halaman…" aria-controls="quicknav-results">
<div class="quicknav-meta"><span data-quicknav-count role="status"></span><span id="quicknav-help">Tab untuk memilih · Enter untuk membuka</span></div>
<div class="quicknav-results" id="quicknav-results" data-quicknav-results></div><p class="quicknav-empty muted" data-quicknav-empty hidden>Tidak ada halaman yang cocok. Coba nama lain.</p>
</div></dialog>
<dialog class="workspace-dialog confirm-dialog" id="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-message">
<div class="dialog-surface">
<div class="dialog-heading"><h2 id="confirm-title" data-confirm-title>Konfirmasi tindakan</h2></div><p id="confirm-message" class="prose" data-confirm-message></p>
<div class="dialog-actions"><button class="button secondary" type="button" data-close-dialog autofocus>Batal</button><button class="button danger" type="button" data-confirm-action>Lanjutkan</button></div>
</div></dialog>
